const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Lake Mead geometry
  const lakeMead = ee.Geometry.Polygon([
    [-114.8, 36.1], [-114.7, 36.1], [-114.7, 36.0], [-114.8, 36.0], [-114.8, 36.1]
  ]);

  // JRC Global Surface Water dataset
  const jrc = ee.Image('JRC/GSW1_4/GlobalSurfaceWater');

  // Get water occurrence for both periods
  const occurrence2000 = jrc.select('occurrence_1');
  const occurrence2022 = jrc.select('occurrence_2');

  // Threshold for water classification (typically > 80% occurrence)
  const water2000 = occurrence2000.gt(80);
  const water2022 = occurrence2022.gt(80);

  // Calculate water area in square meters
  const area2000 = water2000.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMead,
    scale: 1000,
    maxPixels: 1e9
  }).get('occurrence_1');

  const area2022 = water2022.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeMead,
    scale: 1000,
    maxPixels: 1e9
  }).get('occurrence_2');

  const [area2000Val, area2022Val] = await Promise.all([
    area2000.getInfo(),
    area2022.getInfo()
  ]);

  // Print results
  console.log(`2000 Water Area: ${(area2000Val / 1e6).toFixed(2)} km²`);
  console.log(`2022 Water Area: ${(area2022Val / 1e6).toFixed(2)} km²`);
  console.log(`Change: ${((area2022Val - area2000Val) / 1e6).toFixed(2)} km²`);

  // Check for valid data
  if (area2000Val === null || area2022Val === null || 
      isNaN(area2000Val) || isNaN(area2022Val)) {
    console.log("<answer>C3</answer>");
  } else if (area2022Val < area2000Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
